package com.portaregistro;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import java.awt.image.BufferedImage;import java.awt.Color;import java.io.*;import java.time.OffsetDateTime;import javax.imageio.ImageIO;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.Cookie;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class FlowTest {
 @Autowired MockMvc mvc;@Autowired Store s;@Autowired Auth auth;@Autowired ObjectMapper json;@Autowired Jobs jobs;
 String t,other,unit,resident,porter,p,signature;Cookie pc,rc;
 @BeforeEach void init()throws Exception{t=Store.id();other=Store.id();unit=Store.id();resident=Store.id();porter=Store.id();p=Store.id();s.exec("INSERT INTO tenants(id,name) VALUES(?,?)",t,"Teste");s.exec("INSERT INTO tenants(id,name) VALUES(?,?)",other,"Outro");s.exec("INSERT INTO units(id,tenant_id,block_name,number) VALUES(?,?,?,?)",unit,t,"A","101");for(String id:List.of(resident,porter)){s.exec("INSERT INTO accounts(id,name,email,password_hash) VALUES(?,?,?,?)",id,id,id+"@test.com",auth.encoder.encode("TestPassword123456"));}s.exec("INSERT INTO memberships(id,tenant_id,account_id,role,unit_id) VALUES(?,?,?,'RESIDENT',?)",Store.id(),t,resident,unit);s.exec("INSERT INTO memberships(id,tenant_id,account_id,role) VALUES(?,?,?,'PORTER')",Store.id(),t,porter);s.exec("INSERT INTO parcels(id,tenant_id,unit_id,recipient_id,kind,description,volumes,status,created_by) VALUES(?,?,?,?,'INCOMING','Caixa',1,'AVAILABLE',?)",p,t,unit,resident,porter);pc=cookie(porter);rc=cookie(resident);var img=new BufferedImage(300,100,BufferedImage.TYPE_INT_ARGB);var g=img.createGraphics();g.setColor(Color.BLACK);g.fillRect(30,30,180,4);g.dispose();var bytes=new ByteArrayOutputStream();ImageIO.write(img,"png",bytes);signature="data:image/png;base64,"+Base64.getEncoder().encodeToString(bytes.toByteArray());}
 Cookie cookie(String account){String raw=Auth.token();s.exec("INSERT INTO sessions(token_hash,account_id,expires_at) VALUES(?,?,?)",Auth.hash(raw),account,OffsetDateTime.now().plusHours(1));return new Cookie("PR_SESSION",raw);}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder postJson(String path,Map<String,Object> body,Cookie c)throws Exception{return post(path).cookie(c).header("X-Tenant-ID",t).header("X-PortaRegistro","1").contentType("application/json").content(json.writeValueAsBytes(body));}
 @Test void crossTenantDenied()throws Exception{mvc.perform(get("/api/parcels").cookie(pc).header("X-Tenant-ID",other)).andExpect(status().isForbidden());}
 @Test void signatureRequiredAndDuplicateBlocked()throws Exception{mvc.perform(postJson("/api/parcels/"+p+"/complete",Map.of("method","SIGNATURE","collector","Maria","confirmed",true),pc)).andExpect(status().isBadRequest());var body=Map.<String,Object>of("method","SIGNATURE","collector","Maria","confirmed",true,"signature",signature);mvc.perform(postJson("/api/parcels/"+p+"/complete",body,pc)).andExpect(status().isOk());mvc.perform(postJson("/api/parcels/"+p+"/complete",body,pc)).andExpect(status().isConflict());assertEquals(1,s.rows("SELECT * FROM media WHERE parcel_id=?",p).size());}
 @Test void residentConfirmationDistinct()throws Exception{mvc.perform(postJson("/api/parcels/"+p+"/complete",Map.of("method","RESIDENT","confirmed",true),rc)).andExpect(status().isOk());assertEquals("RESIDENT",s.one("SELECT method FROM parcels WHERE id=?",p).get("method"));assertTrue(s.rows("SELECT * FROM media WHERE parcel_id=?",p).isEmpty());}
 @Test void revokedMembershipStopsSession()throws Exception{s.exec("UPDATE memberships SET active=FALSE WHERE account_id=?",porter);mvc.perform(get("/api/parcels").cookie(pc).header("X-Tenant-ID",t)).andExpect(status().isForbidden());}
 @Test void csrfHeaderRequired()throws Exception{mvc.perform(post("/api/auth/logout").cookie(pc)).andExpect(status().isForbidden());}
 @Test void residentCannotAdminister()throws Exception{mvc.perform(postJson("/api/units",Map.of("block","A","number","999"),rc)).andExpect(status().isForbidden());}
 @Test void retentionPreservesSignatureAndPending()throws Exception{var images=new Images(s);images.signature(t,p,signature);images.save(t,p,"PHOTO",new byte[]{1,2,3},"image/jpeg");s.exec("UPDATE parcels SET status='COMPLETED',completed_at=? WHERE id=?",OffsetDateTime.now().minusDays(91),p);jobs.cleanup();assertEquals(0,s.rows("SELECT * FROM media WHERE parcel_id=? AND kind='PHOTO'",p).size());assertEquals(1,s.rows("SELECT * FROM media WHERE parcel_id=? AND kind='SIGNATURE'",p).size());}
 @Test void heldPhotoNotDeleted(){new Images(s).save(t,p,"PHOTO",new byte[]{1,2,3},"image/jpeg");s.exec("UPDATE parcels SET status='COMPLETED',completed_at=?,hold_photo=TRUE WHERE id=?",OffsetDateTime.now().minusDays(91),p);jobs.cleanup();assertEquals(1,s.rows("SELECT * FROM media WHERE parcel_id=?",p).size());}
 @Test void occupantCannotReadEarlierTenancy()throws Exception{s.exec("UPDATE memberships SET created_at=? WHERE account_id=?",OffsetDateTime.now().plusDays(1),resident);mvc.perform(get("/api/parcels/"+p).cookie(rc).header("X-Tenant-ID",t)).andExpect(status().isNotFound());}
}
